package org.example.bookmark;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import org.example.member.Member;
import org.example.post.Post;

import java.time.LocalDateTime;

// 북마크(즐겨찾기) — UNIQUE(member_id, post_id). folder가 null이면 기본 폴더
@Entity
@Table(name = "bookmark")
public class Bookmark {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "member_id", nullable = false)
    private Member member;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "post_id", nullable = false)
    private Post post;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "folder_id")
    private BookmarkFolder folder;

    @Column(length = 200)
    private String memo;

    @Column(name = "created_at", nullable = false)
    private LocalDateTime createdAt;

    @Column(name = "updated_at", nullable = false)
    private LocalDateTime updatedAt;

    protected Bookmark() {
        // JPA
    }

    public Bookmark(Member member, Post post, BookmarkFolder folder, String memo, LocalDateTime now) {
        this.member = member;
        this.post = post;
        this.folder = folder;
        this.memo = memo;
        this.createdAt = now;
        this.updatedAt = now;
    }

    // PUT(upsert)으로 다시 오면 보낸 폴더·메모로 바꾼다(안 보내면 null = 기본 폴더·메모 없음)
    public void change(BookmarkFolder folder, String memo, LocalDateTime now) {
        this.folder = folder;
        this.memo = memo;
        this.updatedAt = now;
    }

    public Long getId() {
        return id;
    }

    public Member getMember() {
        return member;
    }

    public Post getPost() {
        return post;
    }

    public BookmarkFolder getFolder() {
        return folder;
    }

    public String getMemo() {
        return memo;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public LocalDateTime getUpdatedAt() {
        return updatedAt;
    }
}

