import tools.jackson.databind.JsonNode;

@RestController
public class BookmarkController {

    private final BookmarkService bookmarkService;

    public BookmarkController(BookmarkService bookmarkService) {
        this.bookmarkService = bookmarkService;
    }

    @PutMapping("/api/posts/{id}/bookmark")
    public BookmarkResponse bookmark(@PathVariable Long id,
                                     @LoginMember AuthenticatedMember loginMember,
                                     @RequestBody(required = false) JsonNode request) {
        BookmarkRequest body = BookmarkRequest.from(request);
        return bookmarkService.bookmark(id, loginMember, body);
    }

    @DeleteMapping("/api/posts/{id}/bookmark")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void unbookmark(@PathVariable Long id, @LoginMember AuthenticatedMember loginMember) {
        bookmarkService.unbookmark(id, loginMember);
    }
}

